Retrieve all received requests and transactions to identify payments received yesterday from the six coworkers, then create only missing $-denominated requests.

```python
received_requests = []
page_index = 0
while True:
    page = apis.venmo.show_received_payment_requests(
        access_token=venmo_token,
        query="Work Dinner",
        status='pending',
        page_index=page_index,
        page_limit=20
    )
    received_requests.extend(page)
    if len(page) < 20:
        break
    page_index += 1

received_transactions = []
page_index = 0
while True:
    page = apis.venmo.show_transactions(
        access_token=venmo_token,
        page_index=page_index,
        page_limit=20
    )
    received_transactions.extend(page)
    if len(page) < 20:
        break
    page_index += 1

paid_coworkers = set()
for request in received_requests:
    if request['description'] == 'Work Dinner' and request['sender']['name'] in expense_note['content']:
        paid_coworkers.add(request['sender']['name'])
for transaction in received_transactions:
    if transaction['description'] == 'Work Dinner' and transaction['sender']['name'] in expense_note['content']:
        paid_coworkers.add(transaction['sender']['name'])

remaining_shares = {
    name: amount for name, amount in globals().get('expense_note', {}).get('content', {}).items()
    if name not in paid_coworkers
}
print({
    'received_requests': received_requests,
    'received_transactions': received_transactions,
    'paid_coworkers': sorted(paid_coworkers),
    'remaining_shares': remaining_shares
})
